/* Spawn randomized hit particles at joint two, with extra bursts for distant hits. */
void emit_blarg_elite_commando_death_particles(void *m) {
    float delta[4],velocity[4],position[4];
    L16ParticleChoices first,second;
    float distance,range,delay;
    int count;
    void *origin;
    float *joint=position;
    void *movement;
    Moby_GetJointWorldPos(m,2,joint);
    FastVecSub(delta,kalebo3_camera_pos,joint);
    clear_u64_value(velocity);
    distance=FastVecLength(delta);
    if(distance<8.0f) count=truncate_float_to_s32(distance)+2;
    else count=10;
    range=0.0f;
    if(distance<7.0f) range=7.0f-distance;
    origin=position;
    movement=velocity;
    if(count>0) {
    int remaining=count;
    do {
        float sample;
        int *a,*b,duration1,duration2;
        remaining--;
        sample=random_float_between(8.0f,10.0f);
        first=elite_commando_death_spark_start_colors;
        second=elite_commando_death_spark_end_colors;
        delay=sample*g_frame_time-range*g_frame_time;
        a=&first.values[random_integer_below(6)];
        b=&second.values[random_integer_below(6)];
        {int lo=scale_ticks(15),hi=scale_ticks(20);
        duration1=rand_range(lo,hi);
        }
        {int lo=scale_ticks(25),hi=scale_ticks(30);
        duration2=rand_range(lo,hi);
        }
        PartType11Spawn(origin,movement,*a,*b,duration1,duration2,0,0,400000.0f,delay);
    } while(remaining!=0);
    }
    if(*(float *)&blarg_elite_commando_extra_glow_gate<0.95f && distance>9.0f) {
        spawn_glow_particle(m,origin,movement,4.0f,scale_ticks(15),127,127,127,32);
        spawn_glow_particle(m,origin,movement,4.0f,scale_ticks(24),127,32,0,32);
    }
    spawn_glow_particle(m,origin,movement,4.0f,scale_ticks(20),127,64,0,48);
    spawn_glow_particle(m,origin,movement,3.5f,scale_ticks(27),96,16,0,64);
    spawn_glow_particle(m,origin,movement,3.0f,scale_ticks(29),32,0,0,32);
}
