/* Advance a path segment and ease the remaining travel distance. */
int advance_armed_transport_along_path(char *m, char *path) {
    struct ArmedTransportVars *d = (struct ArmedTransportVars *)((Moby *)m)->pvars;
    float progress = (float)d->path_node + d->node_t + d->speed / d->node_length;
    int index = truncate_float_to_s32(progress);
    float speed;
    float distance, rate;
    char *position;
    d->path_node=index;
    d->node_t=progress-(float)index;
    if(index<*(int *)path-1) {
    position=m+0x10;
    SamplePathAt_path42(progress,path,0,position,m+0x40,0);
    d->base_z=((Moby *)m)->pos.z;
    speed=0.0f;
    distance=FastVecDist_path42(position,path+(*(int *)path<<4));
    rate=*(float *)&armed_transport_path_accel*g_frame_time_sq;
    ApproachWithVelocity_path42(distance,rate,rate,*(float *)&armed_transport_max_path_speed*g_frame_time,&speed,&d->speed);
    return 0;
    }
    return 1;
}
typedef struct {
    float x, y, z, heading;
} PathPoint2fa0;
typedef struct {
    int count;
    int pad[3];
    PathPoint2fa0 pts[1];
} Path2fa0;

/* Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/shared/gameplay/vendor/002e22d8.c, FUN_L16_002e2fa0. */
void compute_armed_transport_path_headings(void *arg) {
    Path2fa0 *path = arg;
    int i;
    int n;
    for (i = 0; i < path->count - 1; i++) {
        PathPoint2fa0 *p = path->pts;
        path->pts[i].heading = fast_atan2(path->pts[i + 1].x - path->pts[i].x, p[i + 1].y - path->pts[i].y);
    }
    n = path->count;
    if (n >= 2)
    {
        Path2fa0 *a = (Path2fa0 *)((char *)path + (n - 2) * 16);
        Path2fa0 *b = (Path2fa0 *)((char *)path + (n - 1) * 16);
        b->pts[0].heading = a->pts[0].heading;
    }
}
extern void EaseManipulatorOffsets(char *, char *, int, float, float);

/* Ease the armed transport's two joint offsets toward their targets each frame. */
void update_armed_transport_joint_animation(char *moby)
{
    float ticks = g_frame_scale_sq;
    float a = ticks * 0.03f;
    float b = ticks * 0.3f;
    struct ArmedTransportVars *data = (struct ArmedTransportVars *)((Moby *)moby)->pvars;
    data->turret_pitch = data->unk_17C;
    EaseManipulatorOffsets(moby, data->turret_manip, 2, a, b);
}
