extern char hero_globals_base[];
extern float FastVecDist_r(void *, void *) __asm__("func_001F9D10");
extern void Moby_PlaySound(int, int, int);

/* picks the nearest moby in a list (skipping class 0x5A3) and acts on it */
void group_trigger_nearest(int idx) {
    short *p = kalebo3_moby_groups[idx];
    char *best = 0;
    float bestd = 50000.0f;
    if (p != 0) {
        do {
            char *m = kalebo3_moby_array + ((*(unsigned short *)p & 0x7FFF) << 8);
            if (*(short *)(m + 0xA6) != 0x5A3) {
                float d = FastVecDist_r(&((struct Hero *)((char *)&hero_globals_base + 0xE1D))->motion.pos, m + 0x10);
                if (d < bestd) {
                    bestd = d;
                    best = m;
                }
            }
        } while (*p++ >= 0);
        if (best != 0) {
            Moby_PlaySound(0, 0, (int)best);
        }
    }
}
extern void draw_level16_reflection_mesh_batch(void);
/* Draw-only moby update: after init, queue the reflection mesh draw every frame. */
void moby_update_draw_only(unsigned char *moby) {
    switch (moby[0x20]) {
    case 0:
        moby[0x20] = 1;
        break;
    case 1:
        AddDrawCallback(draw_level16_reflection_mesh_batch, moby);
        break;
    }
}
